#include "../ChunkFillers.h"
#include "inet/features.h"
#ifdef INET_WITH_MQTTSN
#include "inet/applications/mqttsn/MqttSnPacketSerializer.h"
#endif

namespace inet {
// Independently transcribed MQTT-SN v1.2 tables 6–28, not codec-generated bytes.
std::vector<std::vector<uint8_t>> mqttSnWireVectors()
{
    return {{5,0,3,0,20}, {3,1,1}, {3,2,3}, {8,2,3,4,192,0,2,1},
        {7,4,4,1,0,30,'s'}, {3,5,0}, {2,6}, {4,7,0,'w'}, {2,7},
        {2,8}, {4,9,0,255}, {7,10,0,0,0,1,'t'}, {7,11,0,1,0,1,0},
        {9,12,0x40,0,1,0,1,0,255}, {7,13,0,1,0,1,0},
        {4,14,0,1}, {4,15,0,1}, {4,16,0,1}, {6,18,0x20,0,1,'t'},
        {8,19,0x20,0,1,0,1,0}, {6,20,0,0,1,'t'}, {4,21,0,1},
        {3,22,'s'}, {2,23}, {2,24}, {4,24,0,10}, {4,26,0,'w'},
        {2,26}, {3,27,0}, {4,28,0,255}, {3,29,0}, {1,0,4,23},
        {3,5,3}, {6,18,0xa0,0,1,'t'}};
}

void addFillers_mqttsn(std::vector<ChunkFiller>& fillers)
{
#ifdef INET_WITH_MQTTSN
    int index = 0;
    for (auto bytes : mqttSnWireVectors())
        fillers.push_back({"inet::mqttsn::MqttSnPacket", std::to_string(index++), [bytes](Chunk *chunk) {
            *check_and_cast<mqttsn::MqttSnPacket *>(chunk) = *mqttsn::MqttSnPacketSerializer::decode(bytes);
        }});
#endif
}
}
